package com.example.starter.consent;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.Optional;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * 接收方承诺持久化访问：每个“接收方＋主体＋用途＋授权代次”至多一条承诺。
 * 所有 SQL 使用参数绑定；到期时刻以 UTC 时间戳存储。
 */
@Repository
public class AttestationRepository {

    private static final RowMapper<AttestationRow> MAPPER = (rs, rowNum) -> new AttestationRow(
            rs.getString("recipient_key"),
            rs.getString("subject_key"),
            Purpose.valueOf(rs.getString("purpose")),
            rs.getInt("epoch"),
            rs.getTimestamp("expires_at").toInstant(),
            rs.getTimestamp("created_at").toInstant(),
            rs.getString("request_id"));

    private final JdbcTemplate jdbc;

    public AttestationRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 承诺行。
     *
     * @param recipientKey 接收方标识
     * @param subjectKey   授权主体标识
     * @param purpose      承诺用途
     * @param epoch        承诺的授权代次
     * @param expiresAt    UTC 到期时刻，到期时刻恰好到达即失效
     * @param createdAt    UTC 提交时刻
     * @param requestId    创建本承诺的幂等请求标识
     */
    public record AttestationRow(String recipientKey, String subjectKey, Purpose purpose, int epoch,
                                 Instant expiresAt, Instant createdAt, String requestId) {
    }

    Optional<AttestationRow> find(String recipientKey, String subjectKey, Purpose purpose, int epoch) {
        List<AttestationRow> rows = jdbc.query(
                "SELECT recipient_key, subject_key, purpose, epoch, expires_at, created_at, request_id"
                        + " FROM recipient_attestation"
                        + " WHERE recipient_key = ? AND subject_key = ? AND purpose = ? AND epoch = ?",
                MAPPER, recipientKey, subjectKey, purpose.name(), epoch);
        return rows.stream().findFirst();
    }

    Optional<AttestationRow> findForUpdate(String recipientKey, String subjectKey, Purpose purpose, int epoch) {
        List<AttestationRow> rows = jdbc.query(
                "SELECT recipient_key, subject_key, purpose, epoch, expires_at, created_at, request_id"
                        + " FROM recipient_attestation"
                        + " WHERE recipient_key = ? AND subject_key = ? AND purpose = ? AND epoch = ?"
                        + " FOR UPDATE",
                MAPPER, recipientKey, subjectKey, purpose.name(), epoch);
        return rows.stream().findFirst();
    }

    List<AttestationRow> findByRecipient(String recipientKey) {
        return jdbc.query(
                "SELECT recipient_key, subject_key, purpose, epoch, expires_at, created_at, request_id"
                        + " FROM recipient_attestation WHERE recipient_key = ? ORDER BY created_at, id",
                MAPPER, recipientKey);
    }

    void insert(AttestationRow row) {
        jdbc.update(
                "INSERT INTO recipient_attestation"
                        + " (recipient_key, subject_key, purpose, epoch, expires_at, created_at, request_id)"
                        + " VALUES (?, ?, ?, ?, ?, ?, ?)",
                row.recipientKey(), row.subjectKey(), row.purpose().name(), row.epoch(),
                Timestamp.from(row.expiresAt()), Timestamp.from(row.createdAt()), row.requestId());
    }
}

package com.example.starter.consent;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * 读取审计持久化访问：只记录依据承诺成功的读取；撤回不删除历史记录，只追加不修改。
 */
@Repository
public class ReadAuditRepository {

    private static final RowMapper<ReadAuditRow> MAPPER = (rs, rowNum) -> new ReadAuditRow(
            rs.getLong("id"),
            rs.getString("subject_key"),
            rs.getString("recipient_key"),
            Purpose.valueOf(rs.getString("purpose")),
            rs.getInt("epoch"),
            rs.getString("record_key"),
            rs.getTimestamp("read_at").toInstant());

    private final JdbcTemplate jdbc;

    public ReadAuditRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 读取审计行。
     *
     * @param id           审计记录编号
     * @param subjectKey   授权主体标识
     * @param recipientKey 执行读取的接收方标识
     * @param purpose      读取用途
     * @param epoch        读取所依据的授权代次
     * @param recordKey    被读取的记录键
     * @param readAt       UTC 读取时刻
     */
    public record ReadAuditRow(long id, String subjectKey, String recipientKey, Purpose purpose, int epoch,
                               String recordKey, Instant readAt) {
    }

    long insert(String subjectKey, String recipientKey, Purpose purpose, int epoch,
                String recordKey, Instant readAt) {
        jdbc.update(
                "INSERT INTO read_audit (subject_key, recipient_key, purpose, epoch, record_key, read_at)"
                        + " VALUES (?, ?, ?, ?, ?, ?)",
                subjectKey, recipientKey, purpose.name(), epoch, recordKey, Timestamp.from(readAt));
        Long id = jdbc.queryForObject("SELECT IDENTITY()", Long.class);
        return id == null ? -1L : id;
    }

    List<ReadAuditRow> findBySubject(String subjectKey) {
        return jdbc.query(
                "SELECT id, subject_key, recipient_key, purpose, epoch, record_key, read_at"
                        + " FROM read_audit WHERE subject_key = ? ORDER BY id",
                MAPPER, subjectKey);
    }

    int countByRecipientAndRecord(String recipientKey, String subjectKey, Purpose purpose,
                                  int epoch, String recordKey) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM read_audit"
                        + " WHERE recipient_key = ? AND subject_key = ? AND purpose = ? AND epoch = ? AND record_key = ?",
                Integer.class, recipientKey, subjectKey, purpose.name(), epoch, recordKey);
        return count == null ? 0 : count;
    }
}

